    } catch (ex: Exception) {
        JobStatus.TransientFailure
    }

    private fun worker(consumer: ConsumerActor<T, U>, fn: WorkerFunction<T, U>) {
        consumer.subscribe {
            setJobStatus(it, tryJobStatus { runBlocking{fn(it) } })
        }
    }

    fun createFactory() =
